settings.customCss:
.mfp-easter-egg-hunt-registration{--mf-surface:#f6fbfd;--mf-ink:#173e48;--mf-muted:#49636c;--mf-line:#93b4bf;--mf-control:#ffffff;--mf-action:#176c69;--mf-action-ink:#ffffff;--mf-focus:#b34034;--mf-error:#a52f30;box-sizing:border-box;width:100%;max-width:760px;margin:0 auto;background:var(--mf-surface);color:var(--mf-ink);border:1px solid var(--mf-line);border-radius:8px;border-top:5px solid var(--mf-action);overflow:hidden;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;font-size:16px;line-height:1.5;letter-spacing:0}
.mfp-easter-egg-hunt-registration *{box-sizing:border-box;min-width:0}
.mfp-easter-egg-hunt-registration .form-header img{display:block;width:100%;height:176px;object-fit:cover;object-position:center 72%}
.mfp-easter-egg-hunt-registration .form-heading{padding:24px 32px 0}
.mfp-easter-egg-hunt-registration .form-kicker{margin:0 0 6px;color:var(--mf-action);font-size:12px;font-weight:700;text-transform:uppercase}
.mfp-easter-egg-hunt-registration h2{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;font-size:30px;font-weight:750;line-height:1.15;margin:0 0 10px;overflow-wrap:anywhere;letter-spacing:0}
.mfp-easter-egg-hunt-registration .form-heading p:last-child{margin:0;color:var(--mf-muted);font-size:14px}
.mfp-easter-egg-hunt-registration .form-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;padding:26px 32px 0}
.mfp-easter-egg-hunt-registration .field-wide{grid-column:1 / -1}
.mfp-easter-egg-hunt-registration .field-slot{overflow-wrap:anywhere}
.mfp-easter-egg-hunt-registration .field-slot label{display:block;margin-bottom:8px;font-size:14px;font-weight:600;color:var(--mf-ink)}
.mfp-easter-egg-hunt-registration .field-slot input{display:block;width:100%;min-height:46px;border:1px solid var(--mf-line);border-radius:4px;padding:10px 12px;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-easter-egg-hunt-registration .field-slot select{display:block;width:100%;min-height:46px;border:1px solid var(--mf-line);border-radius:4px;padding:10px 12px;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-easter-egg-hunt-registration .field-slot textarea{display:block;width:100%;min-height:88px;resize:vertical;border:1px solid var(--mf-line);border-radius:4px;padding:10px 12px;background:var(--mf-control);color:var(--mf-ink);font:inherit;font-size:16px}
.mfp-easter-egg-hunt-registration .field-slot input::placeholder{color:var(--mf-muted);opacity:1}
.mfp-easter-egg-hunt-registration .field-slot textarea::placeholder{color:var(--mf-muted);opacity:1}
.mfp-easter-egg-hunt-registration .field-slot small{display:block;margin-top:6px;color:var(--mf-muted);font-size:12px}
.mfp-easter-egg-hunt-registration .field-slot [aria-invalid="true"]{border-color:var(--mf-error)}
.mfp-easter-egg-hunt-registration .field-slot [role="alert"]{color:var(--mf-error);font-size:13px;margin-top:6px}
.mfp-easter-egg-hunt-registration .field-slot input:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-egg-hunt-registration .field-slot select:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-egg-hunt-registration .field-slot textarea:focus-visible{outline:3px solid var(--mf-focus);outline-offset:2px}
.mfp-easter-egg-hunt-registration .form-actions{padding:24px 32px 0}
.mfp-easter-egg-hunt-registration .form-actions button{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;min-height:48px;border:0;border-radius:4px;padding:12px 18px;background:var(--mf-action);color:var(--mf-action-ink);font:inherit;font-weight:700;cursor:pointer}
.mfp-easter-egg-hunt-registration .form-actions button:hover{filter:brightness(1.06)}
.mfp-easter-egg-hunt-registration .form-actions button:focus-visible{outline:3px solid var(--mf-focus);outline-offset:3px}
.mfp-easter-egg-hunt-registration .form-actions button:disabled{opacity:0.65;cursor:wait}
.mfp-easter-egg-hunt-registration .form-footer{padding:14px 32px 26px;color:var(--mf-muted);font-size:12px;text-align:center}
.mfp-easter-egg-hunt-registration .field-slot [role="status"]{color:var(--mf-ink);overflow-wrap:anywhere}
@media(max-width:600px){.mfp-easter-egg-hunt-registration .form-header img{height:136px}.mfp-easter-egg-hunt-registration .form-heading{padding:20px 20px 0}.mfp-easter-egg-hunt-registration h2{font-size:28px}.mfp-easter-egg-hunt-registration .form-fields{grid-template-columns:1fr;padding:22px 20px 0;gap:18px}.mfp-easter-egg-hunt-registration .form-actions{padding:22px 20px 0}.mfp-easter-egg-hunt-registration .form-footer{padding:14px 20px 22px}}
.mfp-easter-egg-hunt-registration .form-kicker{text-transform:none;font-size:13px}
.mfp-easter-egg-hunt-registration .form-actions{border-top:1px dashed var(--mf-line);margin:24px 32px 0;padding:20px 0 0}
@media(max-width:600px){.mfp-easter-egg-hunt-registration .form-actions{margin:22px 20px 0;padding:18px 0 0}}
